const ctx = $('Input').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.client_id);
rows.sort((a, b) => String(b.meeting_date).localeCompare(String(a.meeting_date)));
const last = rows[0] ?? null;
return [{ json: { ...ctx, last_meeting_record: last } }];

const ctx = $('Input').first().json;
const userContent = 'Client: ' + ctx.client_name +
'\n\n--- PRIOR MEETING TRANSCRIPT/SUMMARY ---\n' + JSON.stringify($json.last_meeting_record ?? 'No prior meeting on record') +
'\n\n--- CURRENT KARBON WORK ITEMS ---\n' + JSON.stringify(ctx.karbon_items ?? {});
const payload = {
  model: 'claude-opus-4-8',
  max_tokens: 8000,
  system: "You are preparing a CPA for a quarterly client meeting. You are given the prior meeting's transcript/summary and the current list of Karbon work items for the client. For every promise or action item raised in the prior meeting, determine its status by cross-referencing the Karbon work items: Done, Pending, or Blocked. Only mark Done when a work item clearly shows completion. If you cannot tell, use Pending and say why. Do not invent work items. Output only the JSON schema.",
  messages: [{ role: 'user', content: userContent }],
  output_config: { effort: 'high', format: { type: 'json_schema', schema: {"type": "object", "additionalProperties": false, "required": ["promises", "strategies_discussed_not_implemented", "client_questions_raised"], "properties": {"promises": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["item", "owner", "status", "evidence"], "properties": {"item": {"type": "string"}, "owner": {"type": "string", "enum": ["firm", "client", "unclear"]}, "status": {"type": "string", "enum": ["done", "pending", "blocked"]}, "evidence": {"type": "string"}}}}, "strategies_discussed_not_implemented": {"type": "array", "items": {"type": "string"}}, "client_questions_raised": {"type": "array", "items": {"type": "string"}}}} } }
};
return [{ json: { ...$json, payload } }];

// Structured outputs: the JSON arrives as a string in content[0].text.
const text = $json.content?.[0]?.text ?? '{}';
let out; try { out = JSON.parse(text); } catch (e) { out = { parse_error: true, raw: text }; }
const ctx = $('Input').first().json;
return [{ json: { ...ctx, recap: out } }];
